<?php
namespace App\Console\Commands;use App\Services\Warehouse\Hardening\WarehouseGoLiveGateService;use Illuminate\Console\Command;
class WarehouseV2GoLiveGateCommand extends Command{protected $signature='warehouse:v2-go-live-gate {--environment=production} {--json}';protected $description='Menjalankan go-live gate Warehouse v2';public function handle(WarehouseGoLiveGateService $service):int{$data=$service->run(null,(string)$this->option('environment'));$run=$data['run'];if($this->option('json')){$this->line(json_encode($data,JSON_PRETTY_PRINT));}else{$this->table(['Check','Severity','Status','Message'],collect($data['checks'])->map(fn($x)=>[$x->check_code,$x->severity,strtoupper($x->status),$x->message])->all());$this->info("Gate {$run->run_number}: ".strtoupper($run->status));}return in_array($run->status,['passed','passed_with_waiver'],true)?self::SUCCESS:self::FAILURE;}}
